  function picturePicker(kind){screen('tools');softKeys(['','','','','','EXIT'],'picture');const buttons=kind==='pict'?Array.from({length:20},(_,i)=>'<button type="button" data-graph-picture="'+(i+1)+'">PICT'+(i+1)+(workspace.programImageBanks?.pict?.[i+1]?'':' · Empty')+'</button>').join(''):Object.keys(workspace.graphImageFiles).map(name=>'<button type="button" data-graph-file="'+esc(name)+'">'+esc(name)+'</button>').join('');$('.graph-tools').innerHTML='<div class="graph-native-picture-list">'+buttons+(kind==='open'?'<label>OPEN .g3p <input data-graph-picture-open type="file" accept=".g3p"></label>':'')+'</div>';const input=$('[data-graph-picture-open]');input?.addEventListener('change',async()=>{try{const file=input.files[0];if(!file)return;const decoded=await parseG3P(new Uint8Array(await file.arrayBuffer())),name=file.name.replace(/\.[^.]*$/,'').slice(0,8);if(!/^[A-Za-z0-9_]{1,8}$/.test(name))throw Error('Picture name: 1–8 letters, digits or underscores');const picture=encodeProgramPicture({width:decoded.width,height:decoded.height,data:rgb565ToRGBA(decoded.pixels)});if(Object.values(workspace.graphImageFiles).reduce((sum,item)=>sum+(item.picture?.data?.length||0),0)+picture.data.length>1200000)throw Error('Picture memory is full');workspace.graphImageFiles[name]={picture,fingerprint:fingerprint(picture),fade:0,bitDepth:16};commit();chooseBackground({kind:'file',name});}catch(e){error(e.message);}},{signal});}
