  function fadePicture(){if(!pictureRecord())throw Error('No background picture');clearTrace();plot();fadeBuffer='';softKeys(['','','','','',''],'fade');showFade();}
  function setFade(value){if(!Number.isFinite(value)||value<0||value>100)throw Error('Fade: 0–100%');let metadata=backgroundMeta();if(!metadata){metadata={fingerprint:fingerprint(pictureRecord()),fade:0,bitDepth:16};if(settings.background.kind==='pict')workspace.graphPictureMeta[String(settings.background.slot)]=metadata;else Object.assign(workspace.graphImageFiles[settings.background.name],metadata);}metadata.fade=value;commit();showFade();}
