  function visibleCurves(curves){if(drawProgress>=1)return curves;if(!settings.setup.simultaneous)return curves.slice(0,Math.max(1,Math.ceil(curves.length*drawProgress)));return curves.map(curve=>{let remaining=Math.ceil(curve.segments.reduce((n,segment)=>n+segment.length,0)*drawProgress);return {...curve,segments:curve.segments.map(segment=>{const part=segment.slice(0,Math.max(0,remaining));remaining-=part.length;return part;}).filter(segment=>segment.length)};});}
