  function windowPreset(kind){const target=windowSide==='right'?settings.right:settings,turn=calculator.angle==='Rad'?2*Math.PI:calculator.angle==='Gra'?400:360;if(kind==='initial')Object.assign(target,{window:{xmin:-6.3,xmax:6.3,ymin:-3.1,ymax:3.1},xscale:1,yscale:1});else if(kind==='standard')Object.assign(target,{window:{xmin:-10,xmax:10,ymin:-10,ymax:10},xscale:1,yscale:1});else Object.assign(target,{window:{xmin:-turn*1.5,xmax:turn*1.5,ymin:-1.6,ymax:1.6},xscale:turn/4,yscale:.5});target.parameter={min:0,max:turn,step:turn/100};data=null;rightData=null;commit();windowEditor();}
