  function graphMemory(){safely(register);screen('tools');softKeys(['STORE','RECALL','DELETE','','','EXIT'],'memory');const list=document.createElement('div');list.textContent='Graph Memory · '+settings.memories.filter(Boolean).length+'/20';$('.graph-tools').replaceChildren(list);const table=document.createElement('div');settings.memories.forEach((memory,i)=>{const row=document.createElement('div');row.textContent='G-Mem'+(i+1)+'  '+(memory?memory.expressions.filter(Boolean).length+' relations':'Empty');table.append(row);});$('.graph-tools').append(table);}
