  function chooseBuiltin(index){settings.types[selected]='y';fields[selected].value=expressionToLatex(builtins[index]);settings.enabled[selected]=true;register();data=null;edit();}
  function modify(){return safely(()=>{
    register();const candidates=[];for(const [index,r] of activeRelations().entries()){if(!r.expression.trim())continue;const variables=new Set();for(const expr of [r.expression,r.type==='parametric'?r.expression2:''])if(expr)math.parse(graphRelationExpression(expr,r.type)).traverse(node=>{if(node.isSymbolNode&&/^[A-W]$/.test(node.name)&&Object.hasOwn(calculator.vars,node.name))variables.add(node.name);});if(variables.size)candidates.push({index,variables:[...variables].sort()});}
    if(candidates.length!==1||candidates[0].variables.length>5)throw new Error('MODIFY 需要恰好一条含 1–5 个系数变量的启用关系');
    if(!draw())return;selected=candidates[0].index;modifyState={variables:candidates[0].variables,index:0,buffer:''};settings.modify.step=Number.isFinite(settings.modify.step)&&settings.modify.step>0?settings.modify.step:1;plot();softKeys(['VALUE','STEP','','','','EXIT'],'modify');
  });}
  function modifyValue(value){if(!Number.isFinite(value))throw new Error('请输入有限实数');const name=modifyState.variables[modifyState.index];if(name){calculator.vars[name]=value;calculator.approximateVariables?.delete(name);data=sample();}else{if(value<=0)throw new Error('Step 须大于零');settings.modify.step=value;}modifyState.buffer='';paint();commit();}
  function modifyForm(step=false){const current=modifyState,index=current.index;if(step)current.index=current.variables.length;const name=current.variables[current.index]||'Step';parameterForm('MODIFY '+name,[[name,name==='Step'?settings.modify.step:calculator.vars[name]]],v=>{modifyState=current;modifyValue(v[name]);modifyState.index=index;plot();softKeys(['VALUE','STEP','','','','EXIT'],'modify');});}
